export const iconMap: Record<string, IconDefinition> = iconsData.reduce((acc, icon) => {
  acc[icon.name] = icon;
  return acc;
}, {} as Record<string, IconDefinition>);

export function getIcon(name: string): IconDefinition | undefined {
  return iconMap[name];
}
